"""Independent tests for reduce.py (Hamiltonian Cycle -> Hamiltonian Path).

We implement brute-force solvers from the problem definitions, then compare
the source answer with the target answer on the reduction, over many small
instances (exhaustive for n <= 5, plus random for n = 6, 7).
"""

import itertools
import random
import sys

from problems import HamiltonianCycle, HamiltonianPath
from reduce import reduce


# ----------------------------------------------------------------------
# Brute-force solvers written from the definitions.

def _adj(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj


def ham_cycle(n, edges):
    """True iff there is a Hamiltonian cycle (visits every vertex once)."""
    if n <= 2:
        return False
    adj = _adj(n, edges)
    # Fix start vertex 0; try all orderings of the remaining vertices.
    rest = list(range(1, n))
    for perm in itertools.permutations(rest):
        order = (0,) + perm
        ok = True
        for i in range(n):
            a = order[i]
            b = order[(i + 1) % n]
            if b not in adj[a]:
                ok = False
                break
        if ok:
            return True
    return False


def ham_path(n, edges):
    """True iff there is a Hamiltonian path (visits every vertex once)."""
    if n == 0:
        return False
    if n == 1:
        return True
    adj = _adj(n, edges)
    for perm in itertools.permutations(range(n)):
        ok = True
        for i in range(n - 1):
            if perm[i + 1] not in adj[perm[i]]:
                ok = False
                break
        if ok:
            return True
    return False


# ----------------------------------------------------------------------
# Instance generation.

def all_graphs(n):
    verts = list(range(n))
    possible = [(u, v) for u, v in itertools.combinations(verts, 2)]
    for mask in range(1 << len(possible)):
        edges = [list(e) for i, e in enumerate(possible) if (mask >> i) & 1]
        yield {"n": n, "edges": edges}


def random_graph(n, p, rng):
    edges = []
    for u, v in itertools.combinations(range(n), 2):
        if rng.random() < p:
            edges.append([u, v])
    return {"n": n, "edges": edges}


# ----------------------------------------------------------------------
# Test driver.

def main():
    tests_run = 0
    tests_passed = 0
    failures = []

    instances = []
    for n in range(0, 6):
        instances.extend(all_graphs(n))
    rng = random.Random(12345)
    for n in (6, 7):
        for _ in range(300):
            instances.append(random_graph(n, rng.choice([0.2, 0.4, 0.6, 0.8]), rng))

    for inst in instances:
        # Validate source instance.
        HamiltonianCycle.validate(inst)
        src = ham_cycle(inst["n"], inst["edges"])

        red = reduce(inst)
        # The reduction must return a valid target instance.
        HamiltonianPath.validate(red)
        tgt = ham_path(red["n"], red["edges"])

        tests_run += 1
        if src == tgt:
            tests_passed += 1
        else:
            if len(failures) < 10:
                failures.append((inst, src, red, tgt))

    print(f"tests_run={tests_run} tests_passed={tests_passed}")
    for inst, src, red, tgt in failures:
        print("MISMATCH:")
        print("  source instance :", inst, "-> source answer:", src)
        print("  reduced instance:", red, "-> target answer:", tgt)

    return tests_run, tests_passed, len(failures)


if __name__ == "__main__":
    run, passed, nfail = main()
    sys.exit(0 if nfail == 0 else 1)
