def _adj(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj


def ham_cycle(n, edges):
    """True iff some cycle visits every vertex exactly once and returns."""
    if n <= 2:
        return False
    adj = _adj(n, edges)
    rest = list(range(1, n))
    for perm in itertools.permutations(rest):
        order = (0,) + perm
        if all(order[(i + 1) % n] in adj[order[i]] for i in range(n)):
            return True
    return False


def ham_path(n, edges):
    """True iff some path visits every vertex exactly once (any endpoints)."""
    if n == 0:
        return False
    if n == 1:
        return True
    adj = _adj(n, edges)
    for perm in itertools.permutations(range(n)):
        if all(perm[i + 1] in adj[perm[i]] for i in range(n - 1)):
            return True
    return False


# ----------------------------------------------------------------------
# Instance generation.

def all_graphs(n):
    possible = list(itertools.combinations(range(n), 2))
    for mask in range(1 << len(possible)):
        edges = [list(e) for i, e in enumerate(possible) if (mask >> i) & 1]
        yield {"n": n, "edges": edges}


def random_graph(n, p, rng):
    edges = [list(e) for e in itertools.combinations(range(n), 2)
             if rng.random() < p]
    return {"n": n, "edges": edges}


